assert.equal(sha(JSON.stringify(recorded)),'1e743c5fe9ffe7a403ea92b9b365847b17997e31bea3dc4618bb66579e5cab23');
const target=recorded.receipt.pairs[0].a;
test('recorded failed V8 full pair is ready native target-map while its HD city pane was closed',()=>{assert.equal(recorded.status,'ACTUAL_V8_FAILED_BEFORE_TARGET_LCD_CLICK_NOT_DISPATCH');assert.equal(recorded.cityPanel.open,false);assert.equal(recorded.cityPanel.showLcd,false);assert.equal(recorded.receiptPointer,'/stableTicketReceipts/66');assert.equal(recorded.sourceResult.sha256,'0072a022fdaab1afca5403c94ffb2706f893246d55f95b176687157df7db117c');assert.deepEqual(recorded.receipt.pairs[0].a,recorded.receipt.pairs[0].b);assert.equal(impact13DisplayPhase(target),'map');assert.equal(inspectFullTicketPair(target,copy(target)).ready,true);});
test('full pair and cross-retry anchors reject world, owner, reference, key, identity and unknown drift',()=>{const changes=[t=>t.world.cities[6].Food--,t=>t.world.orders[0].Object++,t=>t.state.march.inputSeq++,t=>t.state.snapshot.references.engine++,t=>t.state.keys++,t=>t.meta.currentIdentity=false,t=>t.meta.extraField=1,t=>t.extraRootField=1];const anchor=fullTicketAnchor(target);for(const change of changes){const changed=copy(target);change(changed);assert.throws(()=>inspectFullTicketPair(target,changed),assert.AssertionError);assert.throws(()=>inspectFullTicketPair(changed,copy(changed),anchor),assert.AssertionError);}});
test('cache-only settling keeps complete fields anchored and requires the final two equal tickets',()=>{const previous=copy(target);previous.state.overworld='other';const waiting=inspectFullTicketPair(previous,target);assert.equal(waiting.ready,false);assert.equal(waiting.expected,'map');assert.equal(inspectFullTicketPair(target,copy(target),waiting.anchor).ready,true);const unknown=copy(target);unknown.state.overworld='unknown';assert.throws(()=>inspectFullTicketPair(unknown,copy(unknown)),/Only source-defined cached display phases/);const changed=copy(target);changed.meta.overworldMode='classic';assert.throws(()=>inspectFullTicketPair(changed,copy(changed),waiting.anchor),assert.AssertionError);});
test('controlled report states permit only current3/6 and original3to4 or6to7ok retirement',()=>{const state=copy(target.state);state.march.phase=3;assert.equal(classifyMarchReport(state,3),'current');const next=copy(state);next.march.phase=4;assert.equal(classifyMarchReport(next,3),'naturally-retired');const departure=copy(state);departure.march.phase=6;assert.equal(classifyMarchReport(departure,6),'current');departure.march.phase=7;departure.march.ok=1;assert.equal(classifyMarchReport(departure,6),'naturally-retired');departure.march.ok=0;assert.throws(()=>classifyMarchReport(departure,6),assert.AssertionError);next.march.origin=7;assert.throws(()=>classifyMarchReport(next,3),assert.AssertionError);state.march.phase=7;assert.throws(()=>classifyMarchReport(state,3),assert.AssertionError);});
test('public map presentation permits only the explicitly requested mode in an otherwise exact whole ticket',()=>{const classic=copy(target);classic.meta.overworldMode='classic';assert.deepEqual(assertMapPresentationOnly(target,classic,'classic'),{presentationOnly:true,expectedMode:'classic',nativeInputSent:false,fullTicketExceptOneModeEqual:true});assert.equal(assertMapPresentationOnly(classic,target,'hd-map').presentationOnly,true);const mutations=[t=>t.world.orders[0].Object++,t=>t.state.keys++,t=>t.state.march.inputSeq++,t=>t.state.snapshot.references.data++,t=>t.state.overworld='other',t=>t.meta.cityMode='classic',t=>t.meta.extraField=true,t=>t.extraRootField=true];for(const mutate of mutations){const changed=copy(classic);mutate(changed);assert.throws(()=>assertMapPresentationOnly(target,changed,'classic'),assert.AssertionError);}assert.throws(()=>assertMapPresentationOnly(target,classic,'invalid'),assert.AssertionError);assert.throws(()=>assertMapPresentationOnly(target,classic,'hd-map'),assert.AssertionError);});
test('active owner priority and classic cache agreement preserve complete source-defined semantics',()=>{for(const owner of ['report','fight','spe','result','qty','record']){const state=copy(target);if(['qty','record'].includes(owner))state.state[owner].active=1;else state.state.snapshot[owner].active=1;assert.equal(impact13DisplayPhase(state),'other');assert.equal(inspectFullTicketPair(state,copy(state)).ready,false);}const menu=copy(target);menu.state.menu.active=1;menu.state.menu.context=1;assert.equal(impact13DisplayPhase(menu),'classic-menu');menu.state.menu.context=2;assert.equal(impact13DisplayPhase(menu),'other');const classic=copy(target);classic.meta.overworldMode='classic';classic.state.overworld='other';assert.equal(inspectFullTicketPair(classic,copy(classic)).ready,true);});
test('all exported pure operations leave every supplied ticket and controlled report state unchanged',()=>{const a=copy(target),b=copy(target),priorA=copy(a),priorB=copy(b),report=copy(target.state);report.march.phase=3;const priorReport=copy(report);fullTicketAnchor(a);impact13DisplayPhase(a);inspectFullTicketPair(a,b);classifyMarchReport(report,3);assertMapPresentationOnly(a,b,'hd-map');assert.deepEqual(a,priorA);assert.deepEqual(b,priorB);assert.deepEqual(report,priorReport);});
